289|function parseTaskArgs(argv) {
290|  const flags = {
291|    yolo: false,
292|    trustWorkspace: false,
293|    resumeLast: false,
294|    steps: null,
295|    effort: null,
296|    model: null,
297|    network: null,
298|    allowWorkspaceSwitch: false,
299|    json: false,
300|    promptFile: null,
301|  };
302|  let promptParts = [];
303|  let afterSeparator = false;
304|  let explicitPrompt = null;
305|
306|  for (let i = 0; i < argv.length; i++) {
307|    const a = argv[i];
308|    if (afterSeparator) {
309|      promptParts.push(a);
310|      continue;
311|    }
312|    if (a === "--") {
313|      afterSeparator = true;
314|      continue;
315|    }
316|    if (a === "--yolo") flags.yolo = true;
317|    else if (a === "--trust-workspace") flags.trustWorkspace = true;
318|    else if (a === "--resume-last" || a === "--resume") flags.resumeLast = true;
319|    else if (a === "--allow-workspace-switch") flags.allowWorkspaceSwitch = true;
320|    else if (a === "--json") flags.json = true;
321|    else if (a === "--steps" || a === "--max-model-steps") {
322|      const v = argv[++i];
323|      if (!v) throw new Error("Missing value for --steps");
324|      flags.steps = Number(v);
325|      if (!Number.isFinite(flags.steps) || flags.steps <= 0) throw new Error(`Invalid --steps value: ${v}`);
326|    } else if (a === "--effort" || a === "--reasoning-effort") {
327|      flags.effort = argv[++i];
328|      if (!flags.effort) throw new Error("Missing value for --effort");
329|    } else if (a === "--model") {
330|      flags.model = argv[++i];
331|      if (!flags.model) throw new Error("Missing value for --model");
332|    } else if (a === "--network" || a === "--sandbox-network") {
333|      flags.network = argv[++i];
334|      if (!flags.network) throw new Error("Missing value for --network");
335|    } else if (a === "--prompt-file") {
336|      flags.promptFile = argv[++i];
337|      if (!flags.promptFile) throw new Error("Missing value for --prompt-file");
338|    } else if (a.startsWith("--")) {
339|      throw new Error(`Unknown flag: ${a}`);
340|    } else {
341|      // positional prompt part (before --)
342|      promptParts.push(a);
343|    }
344|  }
345|
346|  // If prompt-file given, read it
347|  if (flags.promptFile) {
348|    const txt = fs.readFileSync(flags.promptFile, "utf8");
349|    explicitPrompt = txt;
350|    // promptParts after -- still appended? No, file is primary
351|    if (promptParts.length) {
352|      // Append any extra parts? Prefer file content + extra
353|      explicitPrompt = explicitPrompt + (promptParts.length ? " " + promptParts.join(" ") : "");
354|    }
355|  } else {
356|    explicitPrompt = promptParts.join(" ");
357|  }
358|
359|  return { flags, prompt: explicitPrompt };
